import { requireRole } from "@/core/server/role-guard";
import { prisma } from "@/core/server/prisma";
import { redirect } from "next/navigation";

export default async function TeacherAnalyticsPage() { const guard = await requireRole(["teacher"]); if (!guard.ok) redirect("/login?reason=session_required"); const whereGroup = { OR: [{ teacherId: guard.user.id }, { teachers: { some: { teacherId: guard.user.id } } }] }; const [groups, activeMembers, submitted, graded] = await Promise.all([prisma.learningGroup.count({ where: whereGroup }), prisma.groupStudent.count({ where: { status: "ACTIVE", group: whereGroup } }), prisma.assignmentSubmission.count({ where: { assignment: { OR: [{ teacherId: guard.user.id }, { group: whereGroup }] }, status: { in: ["SUBMITTED", "LATE", "UNDER_REVIEW"] } } }), prisma.assignmentSubmission.count({ where: { assignment: { OR: [{ teacherId: guard.user.id }, { group: whereGroup }] }, status: "GRADED" } })]); return <section className="space-y-6"><header><h2 className="text-3xl font-bold">Analytics</h2><p className="mt-2 text-slate-600">A privacy-safe overview of the groups you teach.</p></header><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{[["Groups", groups], ["Active learners", activeMembers], ["Awaiting review", submitted], ["Graded submissions", graded]].map(([label, value]) => <article key={String(label)} className="rounded-2xl border bg-white p-5"><p className="text-sm font-semibold text-slate-500">{label}</p><p className="mt-2 text-3xl font-bold">{value}</p></article>)}</div></section>; }
